const urls = [];

for (const item of items) {
  const url =
    item.json.url_File ||
    item.json.urlFile ||
    item.json.webViewLink ||
    item.json.webContentLink ||
    (item.json.id ? `https://drive.google.com/file/d/${item.json.id}/view` : '');

  if (url) urls.push(url);
}

const webhookBody = $('Webhook').first().json.body || {};

return [
  {
    json: {
      baiToan: webhookBody.baiToan || items[0]?.json?.ten_bai_toan || '',
      urlGoc: urls.join('\n'),
      trangThai: 'Chưa làm'
    }
  }
];

// ======================================
// Mục đích:
// Tách tất cả file trong binary thành
// các item riêng biệt để các node phía sau
// (Google Drive Upload, Convert File, Extract Text...)
// xử lý được từng file một.
// ======================================
// Mảng chứa kết quả trả về
const output = [];
// Duyệt toàn bộ item đầu vào
for (const item of items) {
  // Lấy object binary
  // Nếu không tồn tại thì gán object rỗng
  const binary = item.binary || {};
  const keys = Object.keys(binary);
  // Duyệt từng file trong binary
  for (const key of keys) {
    // Lấy thông tin file hiện tại
    const file = binary[key];
    // Tạo item mới cho file này
    output.push({
      // Dữ liệu metadata để tiện debug hoặc lưu DB
      json: {
        originalBinaryKey: key,
        fileName: file.fileName || `file_${output.length + 1}`,
        mimeType: file.mimeType || '',

        // Phần mở rộng file
        // pdf, docx, xlsx...
        fileExtension: file.fileExtension || '',

        // Kích thước file
        fileSize: file.fileSize || ''
      },

      binary: {
        file: file
      }
    });
  }
}
return output;

// 1. Hàm tạo Hash bằng Pure JavaScript (Không gọi require / module external)
function generateHash(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = (hash << 5) - hash + char;
    hash |= 0;
  }
  return Math.abs(hash).toString(16) + '_' + str.length;
}

// 2. Hàm convert dữ liệu động sang dạng Markdown
function convertToMarkdown(data, depth = 2) {
  if (!data) return '';
  if (typeof data === 'string') return data;
  let markdownText = '';
  const prefix = '#'.repeat(Math.min(depth, 6));

  if (Array.isArray(data)) {
    data.forEach((item, index) => {
      if (typeof item === 'object') {
        markdownText += `${prefix} Mục ${index + 1}\n${convertToMarkdown(item, depth + 1)}\n\n`;
      } else {
        markdownText += `- ${item}\n`;
      }
    });
    return markdownText;
  }

  if (typeof data === 'object') {
    for (const [key, value] of Object.entries(data)) {
      if (key.startsWith('_')) continue;
      const readableKey = key.replace(/([A-Z])/g, ' $1').replace(/_/g, ' ').toUpperCase().trim();
      if (typeof value === 'object' && value !== null) {
        markdownText += `${prefix} ${readableKey}\n${convertToMarkdown(value, depth + 1)}\n\n`;
      } else {
        markdownText += `${prefix} ${readableKey}\n${value}\n\n`;
      }
    }
  }
  return markdownText.trim();
}

// 3. Thực thi mã hóa và xuất dữ liệu
const rawInput = $json;
const formattedText = convertToMarkdown(rawInput);
const docHash = generateHash(formattedText);

// Đã đổi thành "Webhook5" theo đúng danh sách node bên trái
const webhookBody = $node["Webhook5"]?.json?.body || $node["Webhook5"]?.json || {};

return [{
  json: {
    doc_hash: docHash,
    text_content: formattedText,
    feature_name: webhookBody.feature_name || "GENERAL_FEATURE",
    project_id: webhookBody.project_id || "DEFAULT_PROJ"
  }
}];

