// ===== Helper parse JSON chịu lỗi (dán lặp lại trong từng Code node) =====
function tryParse(s) { try { return JSON.parse(s); } catch (e) { return null; } }

function salvageArray(t, key) {
  const k = t.indexOf('"' + key + '"');
  if (k < 0) return [];
  let i = t.indexOf('[', k);
  if (i < 0) return [];
  i++;
  const out = [];
  let depth = 0, inStr = false, esc = false, start = -1;
  for (; i < t.length; i++) {
    const c = t[i];
    if (inStr) {
      if (esc) esc = false;
      else if (c === '\\') esc = true;
      else if (c === '"') inStr = false;
      continue;
    }
    if (c === '"') { inStr = true; continue; }
    if (c === '{') { if (depth === 0) start = i; depth++; }
    else if (c === '}') {
      depth--;
      if (depth === 0 && start >= 0) {
        const o = tryParse(t.slice(start, i + 1));
        if (o) out.push(o);
        start = -1;
      }
    } else if (c === ']' && depth === 0) break;
  }
  return out;
}

// Trả về { data, salvaged } hoặc null. arrayKey dùng để cứu các phần tử hoàn chỉnh khi JSON bị cắt cụt.
function parseLoose(raw, arrayKey) {
  let t = String(raw || '').replace(/```json/gi, '').replace(/```/g, '').trim();
  const a = t.indexOf('{'), b = t.lastIndexOf('}');
  if (a >= 0 && b > a) t = t.slice(a, b + 1);
  const attempts = [
    t,
    t.replace(/,\s*([}\]])/g, '$1'),
    t.replace(/[“”]/g, '"').replace(/[‘’]/g, "'").replace(/,\s*([}\]])/g, '$1')
  ];
  for (const s of attempts) {
    const p = tryParse(s);
    if (p && typeof p === 'object') return { data: p, salvaged: false };
  }
  if (arrayKey) {
    const items = salvageArray(t, arrayKey);
    if (items.length) {
      const m = t.match(/"(?:chunk_id|condition_id)"\s*:\s*"([^"]+)"/);
      const data = { [arrayKey]: items };
      if (m) data[t.indexOf('"chunk_id"') >= 0 ? 'chunk_id' : 'condition_id'] = m[1];
      return { data, salvaged: true };
    }
  }
  return null;
}

// Chuẩn hóa test case do AI sinh cho 1 condition; gắn metadata từ condition (không tin AI); không để rơi phân vùng nào.
const first = $input.first().json;
const aiText = first.output || first.text || '';
const arrOf = v => (Array.isArray(v) ? v : v ? [v] : []);

// 1. Xác định condition hiện tại: ưu tiên condition_id mà AI trả lại (tra trong Parse_conditions),
//    nếu không có thì lấy theo item của vòng lặp (Loop Over Items1 -> Wait_Gemini -> AI)
const parsed = String(aiText).trim() ? parseLoose(aiText, 'testcases') : null;
let cond = null;
if (parsed && parsed.data.condition_id) {
  try {
    for (const it of $('Parse_conditions').all()) {
      const f = (it.json.conditions || []).find(c => c.condition_id === parsed.data.condition_id);
      if (f) { cond = f; break; }
    }
  } catch (e) { /* bỏ qua */ }
}
if (!cond) {
  try { cond = $('Wait_Gemini').first().json.conditions || null; } catch (e) { cond = null; }
}
if (!cond) {
  if (!parsed) throw new Error('AI_Phan_tich_Testcase trả JSON không hợp lệ và không xác định được condition.\nRAW:\n' + String(aiText).slice(0, 3000));
  cond = { condition_id: parsed.data.condition_id || '', test_suite: 'General', test_technique: '', condition_type: '', requirement_ids: [] };
}

// 2. Chuẩn hóa danh sách test case
let tcs = parsed && Array.isArray(parsed.data.testcases) ? parsed.data.testcases : [];
const plan = parsed && Array.isArray(parsed.data.phan_vung_ap_dung) ? parsed.data.phan_vung_ap_dung : [];
const notes = [];
if (!tcs.length) notes.push('AI không trả test case hợp lệ cho condition này');
else if (parsed.salvaged) notes.push('JSON test case bị cắt cụt');

function toList(value) {
  if (value === null || value === undefined) return [];
  const a = Array.isArray(value) ? value : String(value).split('\n');
  return a.map(x => String(x === null || x === undefined ? '' : x).trim().replace(/^\d+\s*[\.\)]\s*/, '')).filter(x => x !== '');
}
function buildSteps(pre, steps) {
  const numbered = list => list.map((x, i) => (i + 1) + '. ' + x).join('\n');
  const p = toList(pre), s = toList(steps);
  if (p.length === 0) return numbered(s);
  return 'Pre:\n' + numbered(p) + '\nStep:\n' + numbered(s);
}
function formatResult(v) {
  if (v === null || v === undefined) return '';
  if (Array.isArray(v)) return v.filter(x => x !== null && x !== undefined && String(x).trim() !== '').map(x => String(x).trim()).join('\n');
  return String(v).trim();
}
const startsOk = s => /^(Kiểm tra|Xác minh|Validate)\b/i.test(s);

function fallbackTC(label) {
  const vp = cond.verify_points || {};
  const steps = ['Đăng nhập thành công', 'Truy cập chức năng thuộc "' + (cond.test_suite || '') + '"']
    .concat(arrOf(label ? [label] : cond.test_data_hint).map(h => 'Chuẩn bị/nhập dữ liệu: ' + h))
    .concat(cond.context ? ['Thực hiện thao tác theo ngữ cảnh: ' + cond.context] : [])
    .concat(['Quan sát và đối chiếu kết quả mong muốn']);
  const exp = arrOf(cond.expected_behavior_hint);
  const lines = exp.length ? exp.join('\n- ') : 'N/A (Tài liệu chưa đặc tả)';
  return {
    test_suite: cond.test_suite,
    muc_dich: 'Kiểm tra ' + (cond.condition || '') + (label ? ' - ' + label : ''),
    dieu_kien_tien_quyet: cond.preconditions || [],
    cac_buoc: steps,
    ket_qua_mong_muon: [steps.length + '. - ' + lines],
    _fallback: true
  };
}

// Phân vùng trong kế hoạch mà AI chưa sinh TC -> sinh TC dự phòng để không rơi coverage
if (!tcs.length) {
  const labels = plan.length ? plan : arrOf(cond.test_data_hint);
  tcs = labels.length ? labels.map(l => fallbackTC(l)) : [fallbackTC('')];
} else if (plan.length > tcs.length) {
  notes.push('AI lập kế hoạch ' + plan.length + ' phân vùng nhưng chỉ sinh ' + tcs.length + ' TC');
  for (let i = tcs.length; i < plan.length; i++) tcs.push(fallbackTC(plan[i]));
}

const srcRef = arrOf(cond.requirement_ids).join(', ');
const tag = '[Kỹ thuật: ' + (cond.test_technique || 'N/A') + '] [Loại: ' + (cond.condition_type || 'N/A') + ']' + (srcRef ? ' [Nguồn: ' + srcRef + ']' : '');
const gapNote = cond.requirement_gap ? ' [Thiếu đặc tả: ' + cond.requirement_gap + ']' : '';

return tcs.map(tc => {
  let purpose = String(tc.muc_dich || '').trim();
  if (purpose && !startsOk(purpose)) purpose = 'Kiểm tra ' + purpose.charAt(0).toLowerCase() + purpose.slice(1);
  const review = tc._fallback || cond._generated ? ' [CẦN RÀ SOÁT: ' + (notes.join('; ') || 'nội dung sinh dự phòng, chưa được AI chi tiết hóa') + ']' : '';
  return {
    json: {
      test_suite: cond.test_suite || tc.test_suite || 'General',
      suite_order: cond.suite_order !== undefined ? cond.suite_order : (first.suite_order !== undefined ? first.suite_order : 9999),
      condition_id: cond.condition_id || '',
      muc_dich: purpose,
      cac_buoc: buildSteps(tc.dieu_kien_tien_quyet, tc.cac_buoc),
      ket_qua_mong_muon: formatResult(tc.ket_qua_mong_muon),
      ghi_chu: tag + gapNote + review
    }
  };
}).filter(r => r.json.muc_dich && r.json.cac_buoc);

// Lấy data từ API Figma trả về
const figmaData = $input.first().json;
const documentNode = figmaData.document;

// Lấy thông tin bài toán cũ truyền sang để không bị mất kết nối
const baiToanGoc = $("Switch").item.json; 

// Đệ quy moi móc toàn bộ Text trên giao diện
function extractText(node) {
    let texts = [];
    if (node.type === "TEXT" && node.characters) {
        texts.push(`[${node.name}]: ${node.characters.replace(/\n/g, ' ')}`); 
    }
    if (node.children) {
        for (let child of node.children) {
            texts = texts.concat(extractText(child));
        }
    }
    return texts;
}

const allExtractedText = extractText(documentNode);

// Trả về biến 'data' giống hệt định dạng của nhánh Google Docs
return {
    json: {
        ...baiToanGoc, // Giữ lại tên Bài toán, Link Testcase...
        "data": "DỮ LIỆU GIAO DIỆN TỪ FIGMA:\n" + allExtractedText.join("\n")
    }
};

// 1. Lấy toàn bộ dữ liệu từ node trước đó (nhánh "Chưa làm")
const items = $input.all();
const newItems = [];

// 2. Duyệt qua từng bài toán
for (let i = 0; i < items.length; i++) {
    const item = items[i].json;
    const rawUrls = item["URL"] || "";

    // 3. Tách link: Xử lý cắt chuỗi bằng dấu phẩy (,) hoặc dấu xuống dòng (\n)
    const urlArray = rawUrls.split(/[,\n]+/);

    // 4. Tạo ra các item lẻ cho từng link để node sau dễ đọc
    for (let j = 0; j < urlArray.length; j++) {
        const singleUrl = urlArray[j].trim();

        // Nếu link không bị rỗng thì mới đẩy vào mảng
        if (singleUrl !== "") {
            newItems.push({
                json: {
                    ...item,             // Giữ lại toàn bộ data cũ (Tên bài toán, Link Testcase...)
                    "url_le": singleUrl  // Tạo thêm 1 trường mới chỉ chứa 1 link duy nhất để đọc
                }
            });
        }
    }
}

// 5. Trả về danh sách các link lẻ đã được tách
return newItems;

const items = $input.all();
const grouped = {};

items.forEach(item => {
    const json = item.json;
    const key = json['Bài toán'] || 'Default'; // Gom nhóm theo Tên bài toán

    if (!grouped[key]) {
        // Tạo nhóm mới, giữ lại toàn bộ data gốc
        grouped[key] = { ...json, data: [] };
    }

    // Gom các text tài liệu lẻ vào mảng
    if (json.data) {
        grouped[key].data.push(json.data);
    }
});

// Chạy vòng lặp nối chuỗi mảng thành Text khổng lồ
const results = [];
for (const key in grouped) {
    const finalItem = grouped[key];

    // Chèn Separator siêu đẹp ở đây
    finalItem.data = finalItem.data.join("\n\n--- TÀI LIỆU TIẾP THEO ---\n\n");

    results.push({ json: finalItem });
}

return results;

const items = $input.all();
const baiToanGoc = items[0].json; 

let textContent = `\n\n--- DANH SÁCH API CẦN KIỂM THỬ (BẮT BUỘC ĐỌC) ---\n`;

items.forEach((item) => {
    const data = item.json;
    // Bắt đúng các key từ file Google Sheets của anh
    const tenApi = data["Danh sách api sử dụng "] || "";
    const endpoint = data["col_3"] || data["Đầu api"] || "";
    const moTa = data["col_4"] || data["Mô tả"] || "";

    // Chỉ lấy những dòng có chứa đường link http/api
    if (endpoint.includes("http") || endpoint.includes("api/")) {
        textContent += `\n* Tên API: ${tenApi}\n  - Endpoint: ${endpoint}\n  - Mô tả bổ sung: ${moTa}\n`;
    }
});

return {
    json: {
        "Bài toán": baiToanGoc["Bài toán"],
        "Link Testcase": baiToanGoc["Link Testcase"],
        "Trạng thái": baiToanGoc["Trạng thái"],
        "url_le": baiToanGoc["url_le"],
        "data": textContent
    }
};

// 1. Lấy dữ liệu từ con AI
let text = $('AI_phan_tich_bai_toan').first().json.output || $('AI_phan_tich_bai_toan').first().json.text || "";

// 2. Dọn dẹp thẻ markdown bọc ngoài
text = text.replace(/^```(json|markdown|md)?/im, "");
text = text.replace(/```$/im, "");

// 3. Ép kiểu JSON và GỘP THÀNH 1 ĐOẠN VĂN BẢN
let combinedText = "";
try {
  let parsedData = JSON.parse(text.trim());

  // Gộp các phần lại và tự động thêm tiêu đề cho đẹp
  if (parsedData.muc_tieu_tai_lieu) 
      combinedText += "1. MỤC TIÊU TÀI LIỆU\n" + parsedData.muc_tieu_tai_lieu + "\n\n";

  if (parsedData.he_thong_va_api) 
      combinedText += "2. CÁC HỆ THỐNG VÀ API\n" + parsedData.he_thong_va_api + "\n\n";

  if (parsedData.luong_nghiep_vu) 
      combinedText += "3. LUỒNG NGHIỆP VỤ CHÍNH\n" + parsedData.luong_nghiep_vu + "\n\n";

  if (parsedData.bang_du_lieu) 
      combinedText += "4. CÁC BẢNG DỮ LIỆU\n" + parsedData.bang_du_lieu + "\n\n";

  if (parsedData.test_scenarios) 
      combinedText += "5. KỊCH BẢN KIỂM THỬ (TEST SCENARIOS)\n" + parsedData.test_scenarios + "\n\n";

  if (parsedData.rui_ro_va_cau_hoi) 
      combinedText += "6. RỦI RO / ĐIỂM CHƯA RÕ\n" + parsedData.rui_ro_va_cau_hoi + "\n\n";

  // Đề phòng trường hợp AI trả về key lạ, cứ có nội dung là in ra hết
  if (combinedText === "") {
      for (const key in parsedData) {
          combinedText += `${key.toUpperCase()}:\n${parsedData[key]}\n\n`;
      }
  }

} catch (error) {
  // Nếu lỗi (AI không trả JSON chuẩn), lấy luôn cục chữ nguyên bản của AI
  combinedText = "Nội dung phân tích:\n\n" + text;
}

// 4. TRẢ VỀ ĐÚNG 1 ITEM ĐỂ GOOGLE DOCS IN 1 LẦN
return [{
  json: {
    final_text: combinedText.trim()
  }
}];

const sheetsData = $input.first().json.sheets;
// Móc lại thông tin Bài toán gốc từ node Switch1
const baiToanGoc = $("phân_luồng_tài_liệu").first().json; 

const results = [];
for (const sheet of sheetsData) {
    results.push({
        json: {
            ...baiToanGoc,
            sheet_name: sheet.properties.title
        }
    });
}
return results;

const body = $input.first().json.body;
const newItems = [];

// Trường hợp 1: Nhận mảng từ nút "Chạy các bài đã chọn"
if (body.danhSachBaiToan && Array.isArray(body.danhSachBaiToan)) {
  body.danhSachBaiToan.forEach(task => {
    newItems.push({
      json: {
        baiToan: task,
        promptAI1: body.promptAI1,
        promptAI2: body.promptAI2
      }
    });
  });
} 
// Trường hợp 2: Nhận chuỗi từ nút "Play" của 1 bài đơn lẻ
else if (body.baiToan) {
  newItems.push({
    json: {
      baiToan: body.baiToan,
      promptAI1: body.promptAI1,
      promptAI2: body.promptAI2
    }
  });
}

return newItems;

parameters.text:
=Bạn là Senior Business Analyst kiêm QA Architect.

NHIỆM VỤ
Đọc TOÀN BỘ tài liệu đầu vào và trích xuất yêu cầu có cấu trúc ở mức CHI TIẾT, đủ để các bước sau sinh test case theo các kỹ thuật: Phân vùng tương đương, Phân tích giá trị biên, Bảng quyết định, Chuyển trạng thái, Negative testing, Hồi quy.
- KHÔNG sinh Test Case, Test Scenario, Test Step.
- ĐỦ Ý nhưng GỌN: không bỏ sót quy tắc/trường/trạng thái và không gộp các quy tắc khác nhau, nhưng mỗi chuỗi tối đa ~30 từ và KHÔNG lặp cùng một nội dung ở nhiều khóa (đã ghi ở business_rules thì không chép lại ở validation/exceptions). Khóa "context" của requirement để chuỗi rỗng.

NGUỒN THÔNG TIN DUY NHẤT
Chỉ được dùng (1) nội dung tài liệu và (2) mục "YÊU CẦU BỔ SUNG CỦA NGƯỜI DÙNG" ở cuối. Tuyệt đối KHÔNG suy diễn/bịa thêm Business Rule, Validation, API, bảng/cột, trạng thái, quyền, thông báo, mã lỗi. Nếu chi tiết nào thiếu, ghi đúng chuỗi: "Tài liệu hiện tại chưa đặc tả phần này." và đồng thời ghi vào "ambiguities".

QUY TẮC TRÍCH XUẤT (bắt buộc rà soát từng mục, không bỏ sót):
1. TRƯỜNG NHẬP LIỆU: với mỗi trường ghi đủ (nếu tài liệu có nêu): kiểu dữ liệu, bắt buộc/tùy chọn, độ dài min/max, định dạng, miền giá trị hợp lệ, giá trị mặc định, phụ thuộc vào trường khác. Đưa vào "inputs" và "requirements[].validation". Nếu tài liệu nêu giá trị/ví dụ cụ thể thì giữ NGUYÊN VĂN.
2. QUY TẮC RẼ NHÁNH: mỗi nhánh IF/ELSE là 1 "business_rules" riêng (kể cả nhánh KHÔNG thỏa điều kiện, nhánh mặc định). Khi quyết định phụ thuộc từ 2 điều kiện trở lên, lập thêm "decision_tables" liệt kê đủ các tổ hợp tài liệu cho phép.
3. TRẠNG THÁI: mỗi thực thể có trạng thái (VD STATUS = x) -> ghi đủ các giá trị tài liệu nêu, ý nghĩa, điều kiện chuyển trạng thái; ghi rõ trạng thái nào là HỢP LỆ để thực hiện nghiệp vụ và trạng thái nào KHÔNG hợp lệ.
4. TÍCH HỢP/GỌI HỆ THỐNG: mỗi lần gọi hệ thống khác hay API -> "integrations": hệ thống, endpoint, điều kiện kích hoạt, từng trường trong request payload, phản hồi thành công, từng mã lỗi/phản hồi lỗi, hành vi khi timeout/lỗi, nơi lưu vết log/audit (bảng, file) CHỈ khi tài liệu nêu. Ghi rõ cả điều kiện KHÔNG được gọi.
5. THAY ĐỔI DỮ LIỆU: với mỗi kịch bản (thành công, từ chối, hủy, lỗi, không đổi) ghi "bảng.cột: giá trị trước -> giá trị sau" vào "data_objects[].data_change". Kịch bản không được thay đổi dữ liệu phải ghi rõ "không thay đổi".
6. THÔNG BÁO/LABEL/POPUP: giữ NGUYÊN VĂN trong "expected_behavior" hoặc "error_handling".
7. NGOẠI LỆ: từ chối, hủy, tranh chấp, lỗi hệ thống, thao tác lặp, dữ liệu đã tồn tại/trùng, không tìm thấy... chỉ khi tài liệu nêu -> "exceptions".
8. PHẠM VI THAY ĐỔI & HỒI QUY: xác định phần nào của hệ thống được sửa/thêm mới (changed) và phần nào KHÔNG sửa nhưng đi qua cùng API/module/bảng (unchanged_but_impacted) -> "change_scope". Nếu có, tạo thêm 1 feature riêng tên "Hồi quy các luồng đi qua <tên API/module bị thay đổi>" kèm requirement mô tả hành vi phải giữ nguyên. Nếu tài liệu không nêu luồng nào bị ảnh hưởng, ghi vào ambiguities, KHÔNG tự bịa tên luồng.
9. TÁCH FEATURE THEO TIẾN TRÌNH NGHIỆP VỤ: mỗi feature là một bước/màn hình/luồng riêng (VD: Màn hình nhập liệu -> Kiểm tra dữ liệu trùng -> Gọi hệ thống ngoài -> Phê duyệt -> Xử lý sau phê duyệt -> Ngoại lệ). Đánh "flow_order" = 1..n theo THỨ TỰ THỜI GIAN xử lý thực tế. Mỗi feature chứa tối đa khoảng 8 requirement; nhiều hơn thì tách thành feature con theo bước. KHÔNG gộp cả tài liệu vào 1 feature.
10. Mỗi requirement là 1 hành vi độc lập, kiểm chứng được. Gộp chỉ khi 2 requirement hoàn toàn giống nhau.
11. Giữ nguyên tên kỹ thuật (API, endpoint, bảng, cột, tham số, trạng thái, mã lỗi, job).
12. Mọi giá trị chuỗi trong JSON viết bằng tiếng Việt tự nhiên, văn phong BA chuyên nghiệp (trừ tên kỹ thuật giữ nguyên).
13. Đầu ra là JSON thuần, parse được bằng JSON.parse(): KHÔNG dùng ```json, KHÔNG có chữ ngoài JSON, KHÔNG có dấu phẩy thừa.

