// ===== Helper parse JSON chịu lỗi (dán lặp lại trong từng Code node) =====
function tryParse(s) { try { return JSON.parse(s); } catch (e) { return null; } }

function salvageArray(t, key) {
  const k = t.indexOf('"' + key + '"');
  if (k < 0) return [];
  let i = t.indexOf('[', k);
  if (i < 0) return [];
  i++;
  const out = [];
  let depth = 0, inStr = false, esc = false, start = -1;
  for (; i < t.length; i++) {
    const c = t[i];
    if (inStr) {
      if (esc) esc = false;
      else if (c === '\\') esc = true;
      else if (c === '"') inStr = false;
      continue;
    }
    if (c === '"') { inStr = true; continue; }
    if (c === '{') { if (depth === 0) start = i; depth++; }
    else if (c === '}') {
      depth--;
      if (depth === 0 && start >= 0) {
        const o = tryParse(t.slice(start, i + 1));
        if (o) out.push(o);
        start = -1;
      }
    } else if (c === ']' && depth === 0) break;
  }
  return out;
}

// Trả về { data, salvaged } hoặc null. arrayKey dùng để cứu các phần tử hoàn chỉnh khi JSON bị cắt cụt.
function parseLoose(raw, arrayKey) {
  let t = String(raw || '').replace(/```json/gi, '').replace(/```/g, '').trim();
  const a = t.indexOf('{'), b = t.lastIndexOf('}');
  if (a >= 0 && b > a) t = t.slice(a, b + 1);
  const attempts = [
    t,
    t.replace(/,\s*([}\]])/g, '$1'),
    t.replace(/[“”]/g, '"').replace(/[‘’]/g, "'").replace(/,\s*([}\]])/g, '$1')
  ];
  for (const s of attempts) {
    const p = tryParse(s);
    if (p && typeof p === 'object') return { data: p, salvaged: false };
  }
  if (arrayKey) {
    const items = salvageArray(t, arrayKey);
    if (items.length) {
      const m = t.match(/"(?:chunk_id|condition_id)"\s*:\s*"([^"]+)"/);
      const data = { [arrayKey]: items };
      if (m) data[t.indexOf('"chunk_id"') >= 0 ? 'chunk_id' : 'condition_id'] = m[1];
      return { data, salvaged: true };
    }
  }
  return null;
}

