if (!String(raw).trim()) throw new Error('AI_structured_requirement không trả về dữ liệu.');

const r = parseLoose(raw, 'requirements');
if (!r) throw new Error('Không parse được JSON của AI_structured_requirement.\n\nRAW:\n' + String(raw).slice(0, 4000));

const d = r.data;
if (!Array.isArray(d.requirements) || d.requirements.length === 0) {
