// Parse Test_condition_generator theo từng chunk, chuẩn hóa, và BẢO ĐẢM mọi coverage item đều có >= 1 condition.
const covChunks = $('Parse_Coverage').all().map(i => i.json);
const results = $input.all();
const arrOf = v => (Array.isArray(v) ? v : v ? [v] : []);
const low = x => String(x === null || x === undefined ? '' : x).toLowerCase().trim();
const fuzzy = (a, b) => a && b && a.length >= 2 && b.length >= 2 && (a.includes(b) || b.includes(a));
const anyFuzzy = (text, names) => names.some(n => fuzzy(low(text), n));
const flat = v => arrOf(v).map(low).filter(x => x.length >= 2);
function pick(list, textOf, names, cap) {
  if (!list.length) return [];
  const hit = names.length ? list.filter(x => anyFuzzy(textOf(x), names)) : [];
  if (hit.length) return hit;
  return list.length <= cap ? list : [];
}
const stripPrefix = id => String(id || '').replace(/^.*\//, '');

function conditionFromCoverage(c) {
  return {
    coverage_ids: [c.coverage_id],
    requirement_ids: arrOf(c.requirement_ids),
    test_suite: c.test_suite,
    condition: c.coverage,
    context: c.context || '',
    condition_type: c.polarity || 'Positive',
    test_technique: c.technique || 'Use case',
    preconditions: [],
    test_data_hint: arrOf(c.test_data_hint),
    expected_behavior_hint: arrOf(c.expected_behavior_hint),
    verify_points: { ui: [], network_api: [], log: [], database: [] },
    related_api: arrOf(c.related_api),
    related_fields: arrOf(c.related_fields),
    related_state: arrOf(c.related_state),
    requirement_gap: c.requirement_gap || null,
    _generated: 'coverage_fallback'
  };
}

const out = [];
results.forEach((it, idx) => {
  const raw = it.json.output || it.json.text || '';
  let parsed = null;
  if (String(raw).trim()) parsed = parseLoose(raw, 'conditions');
  const cov = (parsed && covChunks.find(c => c.chunk_id === parsed.data.chunk_id)) || covChunks[idx];
  if (!cov) return;

  let conds = parsed && Array.isArray(parsed.data.conditions) ? parsed.data.conditions : [];
  const warnings = [];
  if (!conds.length) warnings.push('Test_condition_generator không trả dữ liệu hợp lệ -> sinh condition dự phòng từ coverage');
  else if (parsed.salvaged) warnings.push('JSON condition bị cắt cụt, đã cứu ' + conds.length + ' condition');

  // Đảm bảo mọi coverage item có ít nhất 1 condition
  const coveredIds = new Set();
  conds.forEach(c => arrOf(c.coverage_ids).forEach(id => coveredIds.add(stripPrefix(id))));
  const covItems = cov.coverage_items || [];
  covItems.forEach(c => {
    if (!coveredIds.has(stripPrefix(c.coverage_id))) {
      conds.push(conditionFromCoverage(c));
    }
  });

  const reqCtx = cov.requirement_context || {};
  const normalized = conds.map((c, i) => {
    const reqIds = arrOf(c.requirement_ids);
    const idSet = new Set(reqIds);
    const byReq = x => (idSet.size ? idSet.has(x.requirement_id) : true);
    const names = flat(c.related_fields).concat(flat(c.related_state));
    const cond = {
      ...c,
      condition_id: cov.chunk_id + '_C' + String(i + 1).padStart(3, '0'),
      test_suite: cov.suite_name,
      suite_order: cov.suite_order,
      coverage_ids: arrOf(c.coverage_ids),
      requirement_ids: reqIds,
      condition_type: c.condition_type || 'Positive',
      test_technique: c.test_technique || 'Use case',
      preconditions: arrOf(c.preconditions),
      test_data_hint: arrOf(c.test_data_hint),
      expected_behavior_hint: arrOf(c.expected_behavior_hint),
      verify_points: Object.assign({ ui: [], network_api: [], log: [], database: [] }, c.verify_points || {}),
      requirement_gap: c.requirement_gap || null
    };
    const tech = String(cond.test_technique || '');
    const isDT = /quyết định/i.test(tech);
    const isInt = /tích hợp|negative|hồi quy/i.test(tech) || cond.condition_type === 'Regression';
    cond.requirement_context = {
      requirements: (reqCtx.requirements || []).filter(byReq).map(r => ({
        requirement_id: r.requirement_id, requirement: r.requirement,
        expected_behavior: r.expected_behavior, validation: r.validation, error_handling: r.error_handling
      })),
      business_rules: (reqCtx.business_rules || []).filter(byReq),
      decision_tables: isDT ? (reqCtx.decision_tables || []).filter(byReq) : [],
      integrations: isInt ? (reqCtx.integrations || []).filter(byReq) : [],
      exceptions: isInt ? (reqCtx.exceptions || []).filter(byReq) : [],
      inputs: pick(reqCtx.inputs || [], x => x.name, names, 6),
      data_objects: isInt ? pick(reqCtx.data_objects || [], x => (x.table_or_object || '') + ' ' + (x.field || ''), names, 6) : [],
      states: pick(reqCtx.states || [], x => (x.entity || '') + ' ' + (x.state || ''), names, 6),
      change_scope: /hồi quy/i.test(cond.test_technique) || cond.condition_type === 'Regression' ? reqCtx.change_scope : undefined
    };
    return cond;
  });

  out.push({
    json: {
      chunk_id: cov.chunk_id,
      suite_name: cov.suite_name,
      suite_order: cov.suite_order,
      conditions: normalized,
      _warnings: warnings.concat(cov._warnings || [])
    }
  });
});

if (!out.length) throw new Error('Test_condition_generator không trả về dữ liệu cho chunk nào.');
return out;

// Gom test case theo Test Suite, sắp xếp suite theo tiến trình nghiệp vụ (suite_order), loại TC trùng hệt nhau.
const items = $input.all();
if (items.length === 0) return [];

const norm = s => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
const seen = new Set();
const groups = new Map();
let seq = 0;

for (const item of items) {
  const tc = item.json;
  const suite = tc.test_suite && String(tc.test_suite).trim() ? String(tc.test_suite).trim() : 'General';
  const key = suite + '||' + norm(tc.muc_dich) + '||' + norm(tc.cac_buoc) + '||' + norm(tc.ket_qua_mong_muon);
  if (seen.has(key)) continue; // trùng hệt
  seen.add(key);
  if (!groups.has(suite)) groups.set(suite, { order: Number.isFinite(Number(tc.suite_order)) ? Number(tc.suite_order) : 9999, first: seq++, list: [] });
  groups.get(suite).list.push(tc);
}

const ordered = [...groups.entries()].sort((a, b) => (a[1].order - b[1].order) || (a[1].first - b[1].first));

const result = [];
for (const [suite, g] of ordered) {
  result.push({ json: { row_type: 'suite', test_suite: suite, muc_dich: suite, cac_buoc: '', ket_qua_mong_muon: '', ghi_chu: '' } });
  for (const tc of g.list) {
    result.push({
      json: {
        row_type: 'testcase',
        test_suite: suite,
        muc_dich: tc.muc_dich || '',
        cac_buoc: tc.cac_buoc || '',
        ket_qua_mong_muon: tc.ket_qua_mong_muon || '',
        ghi_chu: tc.ghi_chu || ''
      }
    });
  }
}
return result;

