// Trả về { data, salvaged } hoặc null. arrayKey dùng để cứu các phần tử hoàn chỉnh khi JSON bị cắt cụt.
function parseLoose(raw, arrayKey) {
  let t = String(raw || '').replace(/```json/gi, '').replace(/```/g, '').trim();
  const a = t.indexOf('{'), b = t.lastIndexOf('}');
  if (a >= 0 && b > a) t = t.slice(a, b + 1);
  const attempts = [
    t,
    t.replace(/,\s*([}\]])/g, '$1'),
    t.replace(/[“”]/g, '"').replace(/[‘’]/g, "'").replace(/,\s*([}\]])/g, '$1')
  ];
  for (const s of attempts) {
    const p = tryParse(s);
    if (p && typeof p === 'object') return { data: p, salvaged: false };
  }
  if (arrayKey) {
    const items = salvageArray(t, arrayKey);
    if (items.length) {
      const m = t.match(/"(?:chunk_id|condition_id)"\s*:\s*"([^"]+)"/);
      const data = { [arrayKey]: items };
      if (m) data[t.indexOf('"chunk_id"') >= 0 ? 'chunk_id' : 'condition_id'] = m[1];
      return { data, salvaged: true };
    }
  }
  return null;
}

// Parse kết quả Coverage_Expansion theo từng chunk; không để rơi requirement nào.
const chunks = $('Split_By_Feature').all().map(i => i.json);
const results = $input.all();
const arrOf = v => (Array.isArray(v) ? v : v ? [v] : []);
const out = [];
const warnings = [];

function fallbackCoverage(chunk) {
  return (chunk.context.requirements || []).map((r, i) => ({
    coverage_id: 'FB' + String(i + 1).padStart(3, '0'),
    test_suite: chunk.suite_name,
    requirement_ids: [r.requirement_id],
    target_type: 'Business Rule',
    target_name: r.type || '',
    technique: 'Use case',
    coverage_type: 'Alternative Flow',
    polarity: 'Positive',
    coverage: 'Kiểm tra ' + (r.requirement || ''),
    context: r.context || '',
    test_data_hint: [],
    expected_behavior_hint: r.expected_behavior ? [r.expected_behavior] : [],
    related_api: arrOf(r.related_api),
    related_fields: arrOf(r.related_fields),
    related_state: arrOf(r.related_state),
    requirement_gap: 'Coverage sinh dự phòng vì AI không trả JSON hợp lệ cho nhóm này - cần rà soát/bổ sung'
  }));
}

results.forEach((it, idx) => {
  const raw = it.json.output || it.json.text || '';
  let parsed = null;
  if (String(raw).trim()) parsed = parseLoose(raw, 'coverage_items');
  const chunk = (parsed && chunks.find(c => c.chunk_id === parsed.data.chunk_id)) || chunks[idx];
  if (!chunk) { warnings.push('Không xác định được chunk cho kết quả #' + idx); return; }

  let items;
  if (parsed && Array.isArray(parsed.data.coverage_items) && parsed.data.coverage_items.length) {
    items = parsed.data.coverage_items;
    if (parsed.salvaged) warnings.push(chunk.chunk_id + ': JSON bị cắt cụt, chỉ cứu được ' + items.length + ' coverage item');
  } else {
    warnings.push(chunk.chunk_id + ': Coverage_Expansion không trả dữ liệu hợp lệ -> dùng coverage dự phòng');
    items = fallbackCoverage(chunk);
  }

  items = items.map((c, i) => ({
    ...c,
    coverage_id: chunk.chunk_id + '/' + (c.coverage_id || ('COV' + String(i + 1).padStart(3, '0'))),
    test_suite: chunk.suite_name,
    requirement_ids: arrOf(c.requirement_ids),
    test_data_hint: arrOf(c.test_data_hint),
    expected_behavior_hint: arrOf(c.expected_behavior_hint),
    related_api: arrOf(c.related_api),
    related_fields: arrOf(c.related_fields),
    related_state: arrOf(c.related_state)
  }));

  const covered = new Set([].concat(...items.map(c => c.requirement_ids)));
  const uncovered = (chunk.context.requirements || []).map(r => r.requirement_id).filter(id => !covered.has(id));

  out.push({
    json: {
      chunk_id: chunk.chunk_id,
      suite_name: chunk.suite_name,
      suite_order: chunk.suite_order,
      requirement_context: chunk.context,
      coverage_items: items,
      uncovered_requirement_ids: uncovered,
      _warnings: warnings.filter(w => w.startsWith(chunk.chunk_id))
    }
  });
});

if (!out.length) throw new Error('Coverage_Expansion không trả về dữ liệu cho chunk nào. ' + warnings.join(' | '));
return out;

