// Chia dữ liệu requirement thành các chunk theo feature (đúng thứ tự tiến trình nghiệp vụ)
// để mỗi lần gọi AI chỉ xử lý 1 nhóm nhỏ -> không bị cắt cụt/rút gọn, coverage chi tiết hơn.
const s = $input.first().json;
const arr = k => (Array.isArray(s[k]) ? s[k] : []);
const MAX_REQ = 6; // số requirement tối đa trong 1 chunk
const BIG = 1e6;
const num = v => (v === null || v === undefined || v === '' || !Number.isFinite(Number(v)) ? BIG : Number(v));
const low = x => String(x === null || x === undefined ? '' : x).toLowerCase().trim();
const pad = n => String(n).padStart(2, '0');
const flat = v => (Array.isArray(v) ? v : v ? [v] : []).map(low).filter(x => x.length >= 2);
const fuzzy = (a, b) => a && b && a.length >= 2 && b.length >= 2 && (a.includes(b) || b.includes(a));
const anyFuzzy = (text, names) => names.some(n => fuzzy(low(text), n));
// Lọc theo tên; nếu không khớp gì và danh sách nhỏ thì lấy hết
function pick(list, textOf, names, cap) {
  if (!list.length) return [];
  const hit = names.length ? list.filter(x => anyFuzzy(textOf(x), names)) : [];
  if (hit.length) return hit;
  return list.length <= cap ? list : [];
}

const requirements = arr('requirements');
if (!requirements.length) throw new Error('Không có requirement để chia chunk.');

// 1. Sắp xếp feature theo flow_order (tiến trình nghiệp vụ), ổn định theo thứ tự xuất hiện
let features = arr('features').map((f, i) => ({ ...f, _i: i }));
features.sort((a, b) => (num(a.flow_order) - num(b.flow_order)) || (a._i - b._i));
const known = new Set(features.map(f => f.feature_id));
const orphans = requirements.filter(r => !known.has(r.feature_id));
if (orphans.length) {
  features.push({
    feature_id: '__GENERAL__',
    feature_name: features.length ? 'Yêu cầu chung' : (orphans[0].type || 'Yêu cầu chung'),
    description: '', flow_order: BIG, _i: BIG
  });
}
const suiteNames = features.map(f => f.feature_name);

const changeScope = s.change_scope || { changed: [], unchanged_but_impacted: [] };
const baseCtx = {
  all_suites_in_order: suiteNames,
  change_scope: changeScope,
  dependencies: arr('dependencies').slice(0, 30)
};

function buildContext(feature, reqs) {
  const ids = new Set(reqs.map(r => r.requirement_id));
  const names = [].concat(...reqs.map(r => flat(r.related_fields)));
  const apis = [].concat(...reqs.map(r => flat(r.related_api)));
  const sts = [].concat(...reqs.map(r => flat(r.related_state)));
  const byReq = x => ids.has(x.requirement_id);
  return {
    ...baseCtx,
    feature,
    requirements: reqs,
    business_rules: arr('business_rules').filter(byReq),
    decision_tables: arr('decision_tables').filter(byReq),
    integrations: arr('integrations').filter(byReq),
    exceptions: arr('exceptions').filter(byReq),
    flows: arr('flows').filter(f => f.feature_id === feature.feature_id),
    inputs: pick(arr('inputs'), x => x.name, names, 20),
    apis: pick(arr('apis'), x => x.name, apis, 15),
    data_objects: pick(arr('data_objects'), x => (x.table_or_object || '') + ' ' + (x.field || ''), names.concat(sts), 20),
    states: pick(arr('states'), x => (x.entity || '') + ' ' + (x.state || ''), sts.concat(names), 20),
    ambiguities: arr('ambiguities').filter(a => ids.has(a.related_requirement_id))
  };
}

const out = [];
features.forEach((f, idx) => {
  const reqs = requirements.filter(r =>
    f.feature_id === '__GENERAL__' ? !known.has(r.feature_id) : r.feature_id === f.feature_id);
  if (!reqs.length) return;
  const parts = Math.ceil(reqs.length / MAX_REQ);
  for (let p = 0; p < parts; p++) {
    const slice = reqs.slice(p * MAX_REQ, (p + 1) * MAX_REQ);
    const feature = { feature_id: f.feature_id, feature_name: f.feature_name, description: f.description || '' };
    out.push({
      json: {
        chunk_id: 'F' + pad(idx + 1) + (parts > 1 ? '-' + (p + 1) : ''),
        suite_name: f.feature_name,
        suite_order: idx + 1,
        part: p + 1,
        total_parts: parts,
        context: buildContext(feature, slice)
      }
    });
  }
});

// 2. Chunk hồi quy riêng nếu tài liệu có phạm vi thay đổi mà chưa có feature hồi quy
const hasRegression = features.some(f => /hồi quy|regression/i.test(f.feature_name || ''));
const csHas = (changeScope.changed || []).length || (changeScope.unchanged_but_impacted || []).length;
if (csHas && !hasRegression) {
  const order = features.length + 1;
  out.push({
    json: {
      chunk_id: 'F' + pad(order),
      suite_name: 'Hồi quy các luồng bị ảnh hưởng bởi thay đổi',
      suite_order: order,
      part: 1,
      total_parts: 1,
      context: {
        ...baseCtx,
        feature: { feature_id: '__REGRESSION__', feature_name: 'Hồi quy các luồng bị ảnh hưởng bởi thay đổi', description: 'Các luồng đi qua API/module bị thay đổi phải giữ nguyên hành vi cũ.' },
        requirements: requirements.map(r => ({
          requirement_id: r.requirement_id, type: r.type, requirement: r.requirement,
          expected_behavior: r.expected_behavior, preconditions: r.preconditions,
          related_api: r.related_api, related_fields: r.related_fields, related_state: r.related_state
        })),
        business_rules: arr('business_rules'),
        decision_tables: [],
        integrations: arr('integrations'),
        exceptions: [],
        flows: arr('flows'),
        inputs: [],
        apis: arr('apis'),
        data_objects: arr('data_objects').slice(0, 30),
        states: arr('states').slice(0, 30),
        ambiguities: []
      }
    }
  });
}

if (!out.length) throw new Error('Không tạo được chunk nào từ dữ liệu requirement.');
return out;

